<?php
require_once __DIR__ . '/include/config.php';
require_once __DIR__ . '/../include/clinical.php';
hms_start_session();
hms_require_role('doctor');

$doctor = (int) $_SESSION['id'];
$ready = hms_stage6_ready($con);
$error = '';
if ($ready && $_SERVER['REQUEST_METHOD'] === 'POST') {
    hms_verify_csrf();
    try {
        $patient = (int) ($_POST['patient_user_id'] ?? 0);
        $test = hms_post_string('test_name', 180);
        $note = hms_post_string('clinical_note', 1000);
        if (!hms_doctor_patient_allowed($con, $doctor, $patient) || $test === '') {
            throw new InvalidArgumentException('Choose an authorized patient and test name.');
        }
        hms_db_query($con, 'INSERT INTO laboratory_requests(patient_user_id,doctor_id,test_name,clinical_note) VALUES(?,?,?,?)', [$patient, $doctor, $test, $note ?: null]);
        header('Location: laboratory.php?saved=1');
        exit;
    } catch (Throwable $exception) {
        error_log('HMS laboratory request failed: ' . $exception->getMessage());
        $error = $exception instanceof InvalidArgumentException ? $exception->getMessage() : 'Request could not be saved.';
    }
}

$patients = $ready ? hms_clinical_patients($con, $doctor) : null;
$rows = $ready ? hms_db_query($con, 'SELECT l.id,l.test_name,l.status,l.requested_at,u.fullName patient,r.result_value,r.units FROM laboratory_requests l JOIN users u ON u.id=l.patient_user_id LEFT JOIN laboratory_results r ON r.laboratory_request_id=l.id WHERE l.doctor_id=? ORDER BY l.id DESC', [$doctor]) : null;
?>
