lock;margin-top:4px;font-size:11px}@media(max-width:991px){.lab-layout{grid-template-columns:1fr}.lab-form{max-width:none}}@media(max-width:767px){.lab-panel-head{align-items:flex-start;flex-direction:column;gap:4px}.lab-table{min-width:620px}}</style></head>
<body><div id="app"><?php include 'include/sidebar.php'; ?><div class="app-content"><?php include 'include/header.php'; ?><main class="main-content"><div class="wrap-content container lab-workspace"><section id="page-title"><h1 class="mainTitle">Laboratory</h1><ol class="breadcrumb"><li><span>Doctor portal</span></li><li class="active"><span>Laboratory requests</span></li></ol></section><div class="lab-heading"><h1>Laboratory requests</h1><p>Request tests for your authorized patients and review reported results.</p></div>
<?php if (!$ready): ?><div class="alert alert-warning"><?= hms_h(hms_clinical_notice()) ?></div><?php endif; ?><?php if ($error !== ''): ?><div class="alert alert-danger"><?= hms_h($error) ?></div><?php endif; ?><?php if (isset($_GET['saved'])): ?><div class="alert alert-success">Laboratory request created.</div><?php endif; ?>
<div class="lab-layout"><section class="lab-panel"><header class="lab-panel-head"><h2>Requested tests</h2><span><?= $rows ? (int) $rows->num_rows : 0 ?> request<?= $rows && $rows->num_rows === 1 ? '' : 's' ?></span></header><?php if ($rows && $rows->num_rows > 0): ?><div class="table-responsive"><table class="table lab-table"><thead><tr><th>Patient</th><th>Test</th><th>Status</th><th>Result</th></tr></thead><tbody><?php while ($row = $rows->fetch_assoc()): $status = (string) $row['status']; ?><tr><td><span class="lab-patient"><?= hms_h($row['patient']) ?></span><span class="lab-requested"><?= hms_h($row['requested_at']) ?></span></td><td><?= hms_h($row['test_name']) ?></td><td><span class="lab-status <?= hms_h($status) ?>"><?= hms_h(ucfirst(str_replace('_', ' ', $status))) ?></span></td><td><span class="lab-result <?= $row['result_value'] ? '' : 'pending' ?>"><?= hms_h($row['result_value'] ? $row['result_value'] . ($row['units'] ? ' ' . $row['units'] : '') : 'Pending') ?></span></td></tr><?php endwhile; ?></tbody></table></div><?php else: ?><div class="lab-empty"><i class="ti-pulse"></i><strong>No laboratory requests yet</strong><span>New test requests will appear here.</span></div><?php endif; ?></section>
<?php if ($ready): ?><aside class="lab-panel"><form class="lab-form" method="post"><?= hms_csrf_field() ?><h2>Request a test</h2><p>Only patients linked to your care can be selected.</p><label for="lab-patient">Patient</label><select id="lab-patient" name="patient_user_id" class="form-control" required><option value="">Choose patient</option><?php while ($patient = $patients->fetch_assoc()): ?><option value="<?= hms_h($patient['id']) ?>"><?= hms_h($patient['fullName']) ?></option><?php endwhile; ?></select><label for="lab-test">Test name</label><input id="lab-test" class="form-control" name="test_name" maxlength="180" placeholder="e.g. Complete blood count" required><label for="lab-note">Clinical note <span class="text-muted">optional</span></label><textarea id="lab-note" class="form-control" name="clinical_note" maxlength="1000" placeholder="Reason for the requested test"></textarea><button class="btn btn-primary" type="submit"><i class="fa fa-plus"></i> Request test</button></form></aside><?php endif; ?></div></div></main><?php include 'include/footer.php'; ?></div></div><script src="vendor/jquery/jquery.min.js"></script><script src="vendor/bootstrap/js/bootstrap.min.js"></script><script src="vendor/modernizr/modernizr.js"></script><script src="vendor/jquery-cookie/jquery.cookie.js"></script><script src="vendor/perfect-scrollbar/perfect-scrollbar.min.js"></script><script src="vendor/switchery/switchery.min.js"></script><script src="assets/js/main.js"></script><script>jQuery(function(){Main.init();});</script></body></html>
